vi(a){return"\u062a\u0645\u062a \u0625\u0636\u0627\u0641\u0629 @"+a+" \u0628\u0646\u062c\u0627\u062d."},
vv(a,b){return"\u062d\u0633\u0627\u0628\u0627\u062a\u064a ("+a+"/"+b+")"},
vA(a){return"\u0645\u062a\u0628\u0642\u064d "+a+" \u0645\u0643\u0627\u0646"},
vu(a){return"\u062a\u0645 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u062d\u062f \u0627\u0644\u0623\u0642\u0635\u0649 \u0648\u0647\u0648 "+a+" \u062d\u0633\u0627\u0628\u0627\u062a."},
